# Generate 360 unique procedural dispatches by combining officials and problems
dispatches = []
counter = 100

for sec in sectors:
    sec_id = sec["id"]
    sec_name = sec["name"]
    officials = sec["officials"]
    problems = sec["problems"]
    
    for p_idx, prob in enumerate(problems):
        topic, text, req, is_fraud, facts, reason = prob
        for o_idx, official in enumerate(officials):
            disp_id = f"proc_{sec_id}_{p_idx}_{o_idx}"
            sender_str = f"{official} ({sec_name})"
            priority_str = "СРОЧНО" if is_fraud else ("ВЫСОКИЙ" if "fuel" in req or "meds" in req else "СТАНДАРТ")
            
            # Text variations based on official
            var_text = f"Товарищ диспетчер! Докладывает {official}. {text}"
            
            disp = {
                "id": disp_id,
                "isProcedural": True,
                "sectorId": sec_id,
                "sender": sender_str,
                "priority": priority_str,
                "topic": topic,
                "text": var_text,
                "demandSummary": f"Требуется: {list(req.values())[0]} ед. {list(req.keys())[0]}",
                "req": {
                    "fuel": req.get("fuel", 0),
                    "food": req.get("food", 0),
                    "meds": req.get("meds", 0),
                    "ammo": req.get("ammo", 0),
                    "water": req.get("water", 0)
                },
                "telemetryFacts": facts,
                "isFraud": is_fraud,
                "reason": reason
            }
            dispatches.append(disp)

print(f"Total procedural dispatches generated: {len(dispatches)}")

